const devId = msg.payload.end_device_ids.device_id;
const dp = msg.payload.uplink_message.decoded_payload || {};
msg.device_id = devId;
msg.decoded = dp;
// Convention de nommage TTN : teros-zoneN..., vanne-zoneN...
if (devId.startsWith('teros')) return [msg, null];
if (devId.startsWith('vanne')) return [null, msg];
return [null, null];

// Potentiel matriciel (kPa, négatif) + T° sol depuis le payload Dragino décodé par TTN
const d = msg.decoded;
const zone = msg.device_id.replace(/^teros-?/, '') || 'zone1';
let potentiel = d.matric_potential_kpa;
// Fallback : parse de la réponse SDI-12 brute type '0+-40.5+22.3'
if (potentiel === undefined && typeof d.raw_sdi12 === 'string') {
  const m = d.raw_sdi12.match(/([+-]?\d+\.?\d*)\+([+-]?\d+\.?\d*)$/);
  if (m) { potentiel = parseFloat(m[1]); d.soil_temp_c = parseFloat(m[2]); }
}
if (potentiel === undefined) return null;
const mesure = { zone, potentiel_kpa: potentiel, temp_c: d.soil_temp_c, batterie_v: d.battery_v, ts: Date.now() };
const mesures = flow.get('mesures') || {};
mesures[zone] = mesure;
flow.set('mesures', mesures);
msg.payload = mesure;
return msg;

const cfg = flow.get('config') || { seuil_sec: -40, seuil_humide: -10, volume_max_l: 10, auto: false };
cfg[msg.topic] = msg.payload;
flow.set('config', cfg);
node.status({fill:'blue', shape:'dot', text: JSON.stringify(cfg)});
return null;

const cfg = flow.get('config') || { seuil_sec: -40, seuil_humide: -10, volume_max_l: 10, auto: false };
if (!cfg.auto) return null;
const m = msg.payload;
const etats = flow.get('etats_vannes') || {};
const dernierCycle = flow.get('dernier_cycle') || {};
const ANTI_REBOND_MS = 30 * 60 * 1000;
const ouverte = etats[m.zone] === true;
if (m.potentiel_kpa <= cfg.seuil_sec && !ouverte) {
  if (Date.now() - (dernierCycle[m.zone] || 0) < ANTI_REBOND_MS) return null;
  dernierCycle[m.zone] = Date.now();
  flow.set('dernier_cycle', dernierCycle);
  msg.zone = m.zone; msg.commande = 'open'; msg.volume_ml = cfg.volume_max_l * 1000;
  node.warn(`[AUTO] ${m.zone}: ${m.potentiel_kpa} kPa <= ${cfg.seuil_sec} -> OUVERTURE`);
  return msg;
}
if (m.potentiel_kpa >= cfg.seuil_humide && ouverte) {
  msg.zone = m.zone; msg.commande = 'close';
  node.warn(`[AUTO] ${m.zone}: ${m.potentiel_kpa} kPa >= ${cfg.seuil_humide} -> FERMETURE`);
  return msg;
}
return null;

const zone = flow.get('zone_selectionnee');
if (!zone) { node.error('Choisir une zone dans le menu déroulant'); return null; }
const cfg = flow.get('config') || { volume_max_l: 10 };
msg.zone = zone;
msg.commande = msg.payload;  // 'open' ou 'close'
if (msg.commande === 'open') msg.volume_ml = cfg.volume_max_l * 1000;
return msg;

// Mapping zone -> device TTN de la vanne (adapter à vos device IDs)
const VANNES = { zone1: 'vanne-zone1', zone2: 'vanne-zone2', zone3: 'vanne-zone3' };
const APP_ID = env.get('TTN_APP_ID') || 'MON-APP-TTN';
const dev = VANNES[msg.zone];
if (!dev) { node.error('Zone inconnue: ' + msg.zone); return null; }
let bytes;
if (msg.commande === 'close') bytes = [0x00];
else if (msg.volume_ml) { const v = Math.round(msg.volume_ml / 100); bytes = [0x02, (v >> 8) & 0xff, v & 0xff]; }
else bytes = [0x01];
msg.topic = `v3/${APP_ID}@ttn/devices/${dev}/down/push`;
msg.payload = JSON.stringify({ downlinks: [{ f_port: 1, frm_payload: Buffer.from(bytes).toString('base64'), priority: 'NORMAL' }] });
const etats = flow.get('etats_vannes') || {};
etats[msg.zone] = (msg.commande !== 'close');
flow.set('etats_vannes', etats);
return msg;

const d = msg.decoded;
const zone = msg.device_id.replace(/^vanne-?/, '') || 'zone1';
const etats = flow.get('etats_vannes') || {};
etats[zone] = d.valve_open === true;
flow.set('etats_vannes', etats);
msg.payload = { zone, valve_open: d.valve_open, cycle_volume_ml: d.cycle_volume_ml, total_volume_l: d.total_volume_l };
// Alerte : vanne ouverte mais aucun débit
if (d.valve_open && d.cycle_volume_ml === 0) node.warn(`[ALERTE] ${zone}: vanne ouverte sans débit !`);
return msg;

const m = msg.payload;
msg.url = env.get('INFLUX_URL') + '/api/v2/write?org=' + encodeURIComponent(env.get('INFLUX_ORG')) + '&bucket=' + encodeURIComponent(env.get('INFLUX_BUCKET')) + '&precision=ms';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + env.get('INFLUX_TOKEN'), 'Content-Type': 'text/plain' };
let lp = `soil,zone=${m.zone} matric_potential_kpa=${m.potentiel_kpa}`;
if (Number.isFinite(m.temp_c)) lp += `,soil_temp_c=${m.temp_c}`;
if (Number.isFinite(m.batterie_v)) lp += `,battery_v=${m.batterie_v}`;
msg.payload = lp + ' ' + m.ts;
return msg;

const m = msg.payload;
msg.url = env.get('INFLUX_URL') + '/api/v2/write?org=' + encodeURIComponent(env.get('INFLUX_ORG')) + '&bucket=' + encodeURIComponent(env.get('INFLUX_BUCKET')) + '&precision=ms';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + env.get('INFLUX_TOKEN'), 'Content-Type': 'text/plain' };
msg.payload = `irrigation,zone=${m.zone} valve_open=${m.valve_open ? 1 : 0},cycle_volume_ml=${m.cycle_volume_ml || 0},total_volume_l=${m.total_volume_l || 0} ` + Date.now();
return msg;
